package im.nexar.jarvis;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.media.MediaPlayer;import android.net.Uri;import android.os.*;import android.speech.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;

public class MainActivity extends Activity {
 LinearLayout card;TextView status,weather,pairing,answer;EditText question;Button askButton;DesktopApi api;SharedPreferences prefs;SpeechRecognizer recognizer;MediaPlayer currentPlayer;File currentAudioFile;long brainGeneration=0,audioGeneration=0,modelLoadGeneration=0;boolean brainBusy=false;final Handler mainHandler=new Handler(Looper.getMainLooper());int cyan=Color.rgb(190,202,197),white=Color.rgb(232,232,232),muted=Color.rgb(160,160,160);
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("jarvis_private",0);if(!prefs.contains("voice"))prefs.edit().putString("voice",DesktopApi.DEFAULT_VOICE).putString("city",DesktopApi.DEFAULT_CITY).apply();api=new DesktopApi(this,prefs);buildUi();}
 TextView t(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextColor(white);v.setTextSize(z);v.setPadding(18,10,18,10);return v;} Button btn(String s,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setTextColor(cyan);b.setAllCaps(false);b.setOnClickListener(l);return b;}
 void buildUi(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(16,18,16,12);root.setBackgroundColor(Color.rgb(24,24,24));ScrollView sc=new ScrollView(this);card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);TextView h=t("Jarvis",24);h.setTextColor(cyan);card.addView(h);status=t(api.isPaired()?"Desktop verbunden":"Desktop nicht verbunden",16);status.setTextColor(api.isPaired()?cyan:muted);card.addView(status);LinearLayout apps=new LinearLayout(this);apps.setOrientation(LinearLayout.HORIZONTAL);apps.addView(btn("ChatGPT",v->openProvider("com.openai.chatgpt","https://chatgpt.com")),new LinearLayout.LayoutParams(0,-2,1));apps.addView(btn("Claude",v->openProvider("com.anthropic.claude","https://claude.ai")),new LinearLayout.LayoutParams(0,-2,1));apps.addView(btn("Gemini",v->openProvider("com.google.android.apps.bard","https://gemini.google.com")),new LinearLayout.LayoutParams(0,-2,1));card.addView(apps);card.addView(t("Medien",18));LinearLayout media=new LinearLayout(this);for(String[]x:new String[][]{{"Play/Pause","playpause"},{"Zurück","previous"},{"Weiter","next"}})media.addView(btn(x[0],v->remoteMedia(x[1])),new LinearLayout.LayoutParams(0,-2,1));card.addView(media);LinearLayout vol=new LinearLayout(this);for(String[]x:new String[][]{{"Leiser","volumedown"},{"Stumm","mute"},{"Lauter","volumeup"}})vol.addView(btn(x[0],v->remoteMedia(x[1])),new LinearLayout.LayoutParams(0,-2,1));card.addView(vol);card.addView(btn("Mikrofon",v->startSpeech())); addBrainUi();TextView note=t("Voice-Sitzungen werden in der jeweiligen App beendet.",12);note.setTextColor(muted);card.addView(note);weather=t("Wetter wird geladen …",16);card.addView(weather);pairing=t(api.isPaired()?"Gekoppelte Geräte anzeigen":"Geräte koppeln",15);pairing.setTextColor(cyan);pairing.setOnClickListener(v->pairDialog());card.addView(pairing);card.addView(btn("Konto",v->cloudDialog()));card.addView(btn("Einstellungen",v->settingsDialog()));sc.addView(card);root.addView(sc);setContentView(root);loadWeather();}
 void remoteMedia(String action){api.media(action,e->runOnUiThread(()->{if(e!=null)status.setText("Medienfehler: "+e);}));}
 void openProvider(String pkg,String url){try{Intent i=getPackageManager().getLaunchIntentForPackage(pkg);startActivity(i!=null?i:new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception unavailable){status.setText("Anbieter-App oder Browser installieren");}}}
 void loadWeather(){loadWeather(prefs.getString("city",DesktopApi.DEFAULT_CITY));}
 void loadWeather(String city){new Thread(()->{String s=api.weather(city);runOnUiThread(()->weather.setText(s));}).start();}
 void startSpeech(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},7);return;}if(!SpeechRecognizer.isRecognitionAvailable(this)){status.setText("Spracherkennung auf diesem Gerät nicht verfügbar");return;}destroyRecognizer();recognizer=SpeechRecognizer.createSpeechRecognizer(this);recognizer.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){}public void onBeginningOfSpeech(){}public void onRmsChanged(float x){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){}public void onError(int e){status.setText("Spracherkennung beendet (Code "+e+")");}public void onResults(Bundle b){ArrayList<String>a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(a!=null&&!a.isEmpty())handleCommand(a.get(0));}public void onPartialResults(Bundle b){}public void onEvent(int a,Bundle b){}});Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,Locale.GERMAN.toLanguageTag());recognizer.startListening(i);status.setText("Höre sichtbar im Vordergrund …");}
 void handleCommand(String raw){if(raw==null)return;String original=raw.trim();String x=original.toLowerCase(Locale.GERMAN).replaceAll("[^a-zäöüß0-9 ]"," ").replaceAll("\\s+"," ").trim();if(x.equals("jarvis abbrechen")||x.equals("jarvis cancel")){cancelBrain();return;}if(x.equals("abbrechen")||x.equals("cancel")){destroyRecognizer();status.setText("Fremde Voice-Sitzung bitte in Original-App beenden");return;}if(x.equals("chatgpt")||x.equals("chat gpt")||x.equals("öffne chatgpt")||x.equals("öffne chat gpt")){openProvider("com.openai.chatgpt","https://chatgpt.com");status.setText("ChatGPT geöffnet");return;}if(x.equals("claude")||x.equals("öffne claude")){openProvider("com.anthropic.claude","https://claude.ai");status.setText("Claude geöffnet");return;}if(x.equals("gemini")||x.equals("öffne gemini")){openProvider("com.google.android.apps.bard","https://gemini.google.com");status.setText("Gemini geöffnet");return;}if(x.equals("weiter")||x.equals("nächste titel")||x.equals("next")){remoteMedia("next");status.setText("Nächster Titel");return;}if(x.equals("zurück")||x.equals("vorheriger titel")||x.equals("previous")||x.equals("prev")){remoteMedia("previous");status.setText("Vorheriger Titel");return;}if(x.equals("lauter")||x.equals("lautstärke erhöhen")){remoteMedia("volumeup");status.setText("Lautstärke geändert");return;}if(x.equals("leiser")||x.equals("lautstärke verringern")){remoteMedia("volumedown");status.setText("Lautstärke geändert");return;}if(x.equals("stumm")||x.equals("stumm schalten")){remoteMedia("mute");status.setText("Stumm geschaltet");return;}if(x.equals("wetter")||x.equals("wie ist das wetter")){loadWeather();status.setText("Wetter wird geladen …");return;}if(x.matches("(?:wetter|wie ist das wetter) kurz in [a-zäöüß .-]+")){loadWeather(original.substring(original.toLowerCase(Locale.GERMAN).lastIndexOf(" in ")+4).trim());status.setText("Wetter wird geladen …");return;}if(original.length()>=7&&original.regionMatches(true,0,"jarvis ",0,7)){askBrain(original.substring(7).trim());return;}status.setText("Erkannt: "+original);}

 void addBrainUi(){
  card.addView(t("Jarvis Gespräch",18)); question=new EditText(this);question.setHint("Frage an Jarvis …");question.setSingleLine(false);question.setTextColor(white);card.addView(question);
  LinearLayout row=new LinearLayout(this);askButton=btn("Frage stellen",v->askBrain(question.getText().toString().trim()));row.addView(askButton,new LinearLayout.LayoutParams(0,-2,1));row.addView(btn("Abbrechen",v->cancelBrain()),new LinearLayout.LayoutParams(0,-2,1));card.addView(row);
  answer=t("Noch keine Antwort",15);answer.setTextColor(white);card.addView(answer);
 }
 void askBrain(String text){if(text==null||text.trim().isEmpty()){status.setText("Bitte eine Frage eingeben");return;}if(brainBusy){status.setText("Jarvis bearbeitet bereits eine Frage – bitte Abbrechen wählen");return;}if(!api.isPaired()){status.setText("Jarvis läuft über den gekoppelten PC – bitte zuerst einen PC koppeln");return;}final long gen=++brainGeneration;brainBusy=true;if(askButton!=null)askButton.setEnabled(false);status.setText("Jarvis denkt …");answer.setText("Antwort wird geladen …");mainHandler.postDelayed(()->{if(brainBusy&&gen==brainGeneration)cancelBrain();},60000);api.askBrain(text.trim(),(out,provider,model,error)->runOnUiThread(()->{if(gen!=brainGeneration)return;brainBusy=false;if(askButton!=null)askButton.setEnabled(true);if(error!=null){status.setText(error);answer.setText("Keine Antwort");return;}answer.setText(out+"\n\n["+provider+" / "+model+"]");speakAnswer(out);}));}
 void speakAnswer(String text){if(text==null||text.isEmpty())return;final long brainAtFetch=brainGeneration, audioGen=++audioGeneration;api.speak(text,prefs.getString("voice",DesktopApi.DEFAULT_VOICE),(r,e)->runOnUiThread(()->{if(e!=null||brainAtFetch!=brainGeneration||audioGen!=audioGeneration||isFinishing())return;if(e!=null){status.setText("Antwortaudio: "+e);return;}try{stopPlayer();final long playGen=audioGeneration;if(brainAtFetch!=brainGeneration)return;File f=File.createTempFile("jarvis-answer-",".mp3",getCacheDir());currentAudioFile=f;try(FileOutputStream o=new FileOutputStream(f)){o.write(r.audio);}MediaPlayer mp=new MediaPlayer();currentPlayer=mp;File cleanup=f;mp.setDataSource(f.getAbsolutePath());mp.setOnCompletionListener(x->{x.release();if(currentPlayer==x)currentPlayer=null;cleanup.delete();if(currentAudioFile==cleanup)currentAudioFile=null;});mp.setOnErrorListener((x,w,z)->{x.release();if(currentPlayer==x)currentPlayer=null;cleanup.delete();if(currentAudioFile==cleanup)currentAudioFile=null;return true;});mp.prepare();if(playGen!=audioGeneration||brainAtFetch!=brainGeneration){stopPlayer();return;}mp.start();}catch(Exception ex){if(currentAudioFile!=null){currentAudioFile.delete();currentAudioFile=null;}status.setText("Antwort konnte nicht abgespielt werden");}}));}
 void stopPlayer(){audioGeneration++;if(currentPlayer!=null){try{if(currentPlayer.isPlaying())currentPlayer.stop();}catch(Exception ignored){}try{currentPlayer.release();}catch(Exception ignored){}currentPlayer=null;}if(currentAudioFile!=null){currentAudioFile.delete();currentAudioFile=null;}}
 void cancelBrain(){brainGeneration++;brainBusy=false;if(askButton!=null)askButton.setEnabled(true);stopPlayer();api.cancelBrain(e->runOnUiThread(()->status.setText(e==null?"Jarvis abgebrochen":"Abbruch: "+e)));}
 void modelDialog(){if(!api.isPaired()){status.setText("KI-Modelle gibt es über den gekoppelten PC – bitte zuerst koppeln");return;}api.brainState((state,error)->runOnUiThread(()->{if(error!=null){status.setText(error);return;}LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);RadioGroup group=new RadioGroup(this);RadioButton local=new RadioButton(this);local.setId(View.generateViewId());local.setText("Lokal");RadioButton groq=new RadioButton(this);groq.setId(View.generateViewId());groq.setText("Groq");group.addView(local);group.addView(groq);group.check("groq".equals(state.provider)?groq.getId():local.getId());Spinner models=new Spinner(this);l.addView(group);l.addView(models);TextView info=t("Groq-Schlüssel am PC hinterlegen. Schlüssel werden nicht an Android übertragen.",12);info.setTextColor(muted);l.addView(info);final String[] lp={state.localModel},gp={state.groqModel};loadModels("groq".equals(state.provider)?"groq":"local",models);group.setOnCheckedChangeListener((g,id)->loadModels(id==groq.getId()?"groq":"local",models));new AlertDialog.Builder(this).setTitle("KI-Modell").setView(l).setPositiveButton("Speichern",(d,w)->{String provider=group.getCheckedRadioButtonId()==groq.getId()?"groq":"local";Object selected=models.getSelectedItem();String model=selected instanceof DesktopApi.BrainModel?((DesktopApi.BrainModel)selected).id:(selected==null?"":selected.toString());if(model.isEmpty()){status.setText("Bitte ein Modell auswählen");return;}api.saveBrain(provider,"local".equals(provider)?model:lp[0],"groq".equals(provider)?model:gp[0],e->runOnUiThread(()->status.setText(e==null?"KI-Modell gespeichert":"Speichern fehlgeschlagen: "+e)));}).setNegativeButton("Abbrechen",null).show();}));}
 void loadModels(String provider,Spinner target){final long gen=++modelLoadGeneration;target.setTag(provider);target.setAdapter(new ArrayAdapter<DesktopApi.BrainModel>(this,android.R.layout.simple_spinner_dropdown_item,new ArrayList<>()));api.brainModels(provider,(models,error)->runOnUiThread(()->{if(gen!=modelLoadGeneration||!provider.equals(target.getTag()))return;if(error!=null){status.setText(error);return;}target.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,models));}));}
 void destroyRecognizer(){if(recognizer!=null){try{recognizer.cancel();}catch(Exception e){}recognizer.destroy();recognizer=null;}}
 @Override public void onRequestPermissionsResult(int r,String[]p,int[]g){super.onRequestPermissionsResult(r,p,g);if(r==7&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)startSpeech();else if(r==7)status.setText("Mikrofonberechtigung erforderlich");}
 void pairDialog(){EditText e=new EditText(this);e.setHint("Einladung vom PC");new AlertDialog.Builder(this).setTitle("Desktop koppeln").setMessage("Einladung aus der PC-App einfügen.").setView(e).setPositiveButton("Koppeln",(d,w)->new Thread(()->{String r=api.pair(e.getText().toString());runOnUiThread(()->{status.setText(r);status.setTextColor(api.isPaired()?cyan:muted);});}).start()).setNegativeButton("Abbrechen",null).show();}
 void settingsDialog(){LinearLayout l=new LinearLayout(this);l.setPadding(12,0,12,0);l.setOrientation(LinearLayout.VERTICAL);EditText voice=new EditText(this);voice.setHint("Stimme");voice.setTag(prefs.getString("voice",DesktopApi.DEFAULT_VOICE));voice.setText(((String)voice.getTag()).replaceAll("^.*-([^-]+)Neural$","$1"));voice.setFocusable(false);voice.setKeyListener(null);l.addView(voice);if(api.isPaired())l.addView(btn("Stimme suchen",v->voiceBrowser(voice)));else{TextView hint=t("Stimmen vom gekoppelten PC",13);hint.setTextColor(muted);l.addView(hint);}l.addView(btn("Stimme anhören",v->preview((String)voice.getTag())));l.addView(btn("KI-Modell",v->modelDialog()));EditText city=new EditText(this);city.setHint("Wetterort");city.setText(prefs.getString("city",DesktopApi.DEFAULT_CITY));l.addView(city);new AlertDialog.Builder(this).setTitle("Einstellungen").setView(l).setPositiveButton("Speichern",(d,w)->{String v=(String)voice.getTag(),c=city.getText().toString().trim();api.saveLocalSettings(v.isEmpty()?DesktopApi.DEFAULT_VOICE:v,c.isEmpty()?DesktopApi.DEFAULT_CITY:c);new Thread(()->api.syncProfile()).start();loadWeather();}).setNegativeButton("Abbrechen",null).show();}
 void voiceBrowser(EditText target){final EditText filter=new EditText(this);filter.setHint("Name, Sprache oder Land");final ListView list=new ListView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.addView(filter);box.addView(list,new LinearLayout.LayoutParams(-1,0,1));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Stimme").setView(box).setNegativeButton("Schließen",null).create();dialog.show();api.voices((voices,error)->runOnUiThread(()->{if(error!=null){status.setText(error);dialog.dismiss();return;}ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1);list.setAdapter(adapter);Runnable apply=()->{String q=filter.getText().toString().toLowerCase(Locale.GERMAN);adapter.clear();for(DesktopApi.Voice v:voices)if(v.shortName.toLowerCase(Locale.GERMAN).contains(q)||v.locale.toLowerCase(Locale.GERMAN).contains(q)||v.gender.toLowerCase(Locale.GERMAN).contains(q)||v.friendlyName.toLowerCase(Locale.GERMAN).contains(q)||v.label().toLowerCase(Locale.GERMAN).contains(q))adapter.add(v.label());adapter.notifyDataSetChanged();};apply.run();filter.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int d){}public void onTextChanged(CharSequence s,int a,int b,int d){apply.run();}public void afterTextChanged(android.text.Editable e){}});list.setOnItemClickListener((p,v,pos,id)->{String label=adapter.getItem(pos);for(DesktopApi.Voice x:voices)if(x.label().equals(label)){target.setText(x.label());target.setTag(x.shortName);break;}dialog.dismiss();});}));}
 void preview(String voice){if(voice.isEmpty())voice=DesktopApi.DEFAULT_VOICE;if(!api.isPaired()){status.setText("Für die Vorschau mit dem PC verbinden");return;}final String selected=voice;final long gen=++audioGeneration;status.setText("Sprachvorschau wird geladen …");api.speak("Guten Tag. Ich bin Jarvis.",selected,(result,error)->runOnUiThread(()->{if(gen!=audioGeneration||isFinishing())return;if(error!=null){status.setText("Vorschaufehler: "+error);return;}try{stopPlayer();final long playGen=audioGeneration;if(gen!=playGen)return;File f=File.createTempFile("jarvis-preview-",".mp3",getCacheDir());currentAudioFile=f;try(FileOutputStream out=new FileOutputStream(f)){out.write(result.audio);}MediaPlayer mp=new MediaPlayer();currentPlayer=mp;File cleanup=f;mp.setDataSource(f.getAbsolutePath());mp.setOnCompletionListener(x->{x.release();if(currentPlayer==x)currentPlayer=null;cleanup.delete();if(currentAudioFile==cleanup)currentAudioFile=null;});mp.setOnErrorListener((x,w,e)->{x.release();if(currentPlayer==x)currentPlayer=null;cleanup.delete();if(currentAudioFile==cleanup)currentAudioFile=null;return true;});mp.prepare();if(playGen!=audioGeneration){stopPlayer();return;}mp.start();status.setText("Vorschau: "+selected);}catch(Exception e){if(currentAudioFile!=null){currentAudioFile.delete();currentAudioFile=null;}status.setText("Vorschau konnte nicht abgespielt werden");}}));}

 void cloudDialog(){if(api.isSignedIn()){new AlertDialog.Builder(this).setTitle("Konto").setMessage(api.cloudStatus()).setPositiveButton("Abmelden",(d,w)->new Thread(()->{api.cloudLogout();runOnUiThread(()->status.setText("Konto abgemeldet"));}).start()).setNegativeButton("Schließen",null).show();return;}if(!api.cloudConfigured()){new AlertDialog.Builder(this).setTitle("Konto").setMessage("Konto ist nicht eingerichtet").setPositiveButton("OK",null).show();return;}LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText email=new EditText(this);email.setHint("E-Mail");email.setInputType(33);email.setText(api.secure.get("email"));l.addView(email);EditText pass=new EditText(this);pass.setHint("Passwort");pass.setInputType(129);l.addView(pass);TextView info=t("E-Mail und Passwort. "+api.cloudStatus(),12);info.setTextColor(muted);l.addView(info);new AlertDialog.Builder(this).setTitle("Konto").setView(l).setPositiveButton("Anmelden",(d,w)->cloudAction(false,email.getText().toString(),pass.getText().toString())).setNeutralButton("Registrieren",(d,w)->cloudAction(true,email.getText().toString(),pass.getText().toString())).setNegativeButton("Abbrechen",null).show();}
 void cloudAction(boolean signup,String e,String pw){new Thread(()->{String r=signup?api.cloudSignup(e,pw):api.cloudLogin(e,pw);api.syncProfile();String st=api.cloudStatus();runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Konto").setMessage(r+"\n"+st).setPositiveButton("OK",null).setNeutralButton("Abmelden",(d,w)->new Thread(()->{api.cloudLogout();runOnUiThread(()->status.setText("Konto abgemeldet"));}).start()).show());}).start();}
 @Override protected void onResume(){super.onResume();api.startPolling(()->runOnUiThread(()->{if(api.isPaired())status.setText("Desktop synchronisiert");loadWeather();}));}
 @Override protected void onPause(){brainGeneration++;brainBusy=false;if(askButton!=null)askButton.setEnabled(true);api.stopPolling();destroyRecognizer();stopPlayer();super.onPause();}
 @Override protected void onDestroy(){stopPlayer();destroyRecognizer();super.onDestroy();}
}
